class Solution {
    unordered_set<string> seen;
    string ans = "";
    void dfs(const string& node, int k) {
        for (int x = 0; x < k; x++) {
            string edge = node + to_string(x);
            if (!seen.count(edge)) {
                seen.insert(edge);
                dfs(edge.substr(1), k);
                ans += to_string(x);
            }
        }
    }
public:
    string crackSafe(int n, int k) {
        string start(n - 1, '0');
        dfs(start, k);
        reverse(ans.begin(), ans.end());
        return ans + start;
    }
};

class Solution {
    private Set<String> seen = new HashSet<>();
    private StringBuilder ans = new StringBuilder();
    public String crackSafe(int n, int k) {
        StringBuilder start = new StringBuilder();
        for (int i = 0; i < n - 1; i++) start.append('0');
        dfs(start.toString(), k);
        return ans.reverse().toString() + start.toString();
    }
    private void dfs(String node, int k) {
        for (int x = 0; x < k; x++) {
            String edge = node + x;
            if (!seen.contains(edge)) {
                seen.add(edge);
                dfs(edge.substring(1), k);
                ans.append(x);
            }
        }
    }
}

var crackSafe = function(n, k) {
    const seen = new Set();
    const ans = [];
    function dfs(node) {
        for (let x = 0; x < k; x++) {
            const edge = node + x;
            if (!seen.has(edge)) {
                seen.add(edge);
                dfs(edge.slice(1));
                ans.push(String(x));
            }
        }
    }
    const start = '0'.repeat(n - 1);
    dfs(start);
    ans.reverse();
    return ans.join('') + start;
};
